<template>
  <div class="flex flex-col gap-3">
    <!-- Toolbar: Search + Add User -->
    <div class="flex items-center gap-2">
      <q-input outlined debounce="300" color="primary" v-model="filter" autofocus dense>
        <template v-slot:append>
          <q-icon name="search" />
        </template>
      </q-input>
      <q-space />
      <f-btn :label="$t('add_user')" @click="openUserDlg()" />
    </div>

    <!-- Table -->
    <DocBitsTable
      :rows="filteredRows"
      :columns="columns"
      row-key="id"
      table-id="sub_org_users_table"
      :loading="processing || user_list_loading"
      :features="{
        sorting: false,
        filtering: false,
        selection: false,
        bulkActions: false,
        rowActions: true,
        resizable: false,
        pagination: false,
        columnReorder: false,
        stickyLastColumn: true,
      }"
      :row-actions="rowActions"
      no-data-label="no_record_found"
      table-height="60vh"
      flat-style
      @row-action="handleRowAction"
    />
  </div>

  <q-dialog
    v-model="add_users_dialog"
    persistent
    transition-show="scale"
    transition-hide="scale"
    @keydown.esc="add_users_dialog = false"
  >
    <AddUser :sub_org_id="sub_org_id" :sub_org_users="sub_org_users"></AddUser>
  </q-dialog>
</template>

<script lang="ts">
import { useDropdownStore } from 'src/store/main';
import helperMixin from 'src/mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import { defineComponent, ref } from 'vue';
import { subOrgsApiService } from 'src/services';
import { storeToRefs } from 'pinia';
import AddUser from './AddUser.vue';
import { notify } from 'src/components/notifications/notify';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';
import type { RowActionItem, UnifiedTableColumn } from 'src/components/Table/types/table/unified-table';

export default defineComponent({
  mixins: [helperMixin],
  components: {
    AddUser,
    DocBitsTable,
  },
  props: {
    sub_org_id: {
      type: String,
      default: '',
    },
  },
  data() {
    return {};
  },
  computed: {
    filteredRows(): any[] {
      if (!this.filter) return this.rows;
      const needle = this.filter.toLowerCase();
      return this.rows.filter((row: any) =>
        (row.user_name || '').toLowerCase().includes(needle),
      );
    },
  },
  mounted: function () {
    this.init();
    document.addEventListener('user_added', this.userAdded);
  },
  methods: {
    async init() {
      try {
        this.processing = true;
        await this.prepareTableData();
        await this.prepareUsersDropdown();
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },
    userAdded(e: any) {
      if (!e || !e.detail) {
        return;
      }
      this.add_users_dialog = false;
      this.addNewUserToListView(e.detail);
    },

    addNewUserToListView(user_id: string) {
      const newUser = JSON.parse(JSON.stringify(this.usersMap.get(user_id)));
      newUser['user_name'] = newUser.first_name + ' ' + newUser.last_name;
      this.rows.push(newUser);
    },

    async prepareTableData() {
      await this.getGroupUsers();
      this.prepareTableColumns();
      this.prepareTableRows();
    },
    async getGroupUsers() {
      let response = null;
      this.processing = true;
      try {
        response = await subOrgsApiService.getSubOrgUsers(this.sub_org_id);
        if (!response) {
          throw response;
        }
        this.sub_org_users = response;
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },
    prepareTableColumns() {
      this.columns = [
        {
          name: 'user_name',
          label: this.$t('name'),
          field: 'user_name',
          align: 'left',
        },
      ] as UnifiedTableColumn[];
    },

    prepareTableRows() {
      this.rows = [];
      for (let user of this.sub_org_users) {
        user['user_name'] = user.first_name + ' ' + user.last_name;
      }
      this.rows = this.sub_org_users;
    },

    async removeUser(user_id: number) {
      this.processing = true;
      try {
        await subOrgsApiService.deleteUserFromSubOrg(
          this.sub_org_id,
          String(user_id),
        );
        this.removeUserFromListView(user_id);
        const event = new CustomEvent('sub_org_user_removed', {
          detail: { user_id: user_id, sub_org_id: this.sub_org_id },
        });
        document.dispatchEvent(event);
        notify.success(this.$t('message_success_with_await'));
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },

    removeUserFromListView(user_id: number) {
      const data_index = this.rows.findIndex((row: any) => row.id === user_id);
      if (data_index === -1) {
        return;
      }
      this.rows.splice(data_index, 1);
    },

    handleRowAction({ action, row }: { action: string; row: any }) {
      if (action === 'delete') {
        this.removeUser(row.id);
      }
    },

    openUserDlg() {
      this.add_users_dialog = true;
    },
  },
  setup() {
    const filter = ref('');
    const columns = ref([] as UnifiedTableColumn[]);

    const dropdown_store = useDropdownStore();
    const { usersMap, user_list_loading } = storeToRefs(dropdown_store);
    const { prepareUsersDropdown } = dropdown_store;

    const rowActions: RowActionItem[] = [
      { key: 'delete', label: 'delete', icon: 'delete', color: 'negative', separator: true },
    ];

    return {
      user_list_loading,
      prepareUsersDropdown,
      filter,
      columns,
      usersMap,
      rowActions,
      rows: ref([] as any[]),
      loading: ref(false),
      sub_org_users: ref([] as any),
      add_users_dialog: ref(false),
      processing: ref(false),
    };
  },
});
</script>
