<!--vbase-->
<template>
  <q-card style="width: 600px">
    <form @submit.prevent.stop="submitNewColumFrom">
      <q-toolbar class="text-white secondary-toolbar">
        <q-toolbar-title v-if="is_edit"
          ><span class="text-weight-bold">{{
            $t('edit_sub_organization')
          }}</span>
        </q-toolbar-title>
        <q-toolbar-title v-else
          ><span class="text-weight-bold">{{ $t('create_sub_org') }}</span>
        </q-toolbar-title>

        <q-btn flat round dense icon="close" class="text-white" v-close-popup />
      </q-toolbar>

      <q-card-section class="q-pt-none">
        <div style="margin-bottom: 20px" class="row full-width mb-10 mt-8">
          <div class="full-width">
            <q-input
              outlined
              tabindex="0"
              :class="
                'full-width ' +
                (!new_model['validate'] || new_model['required_error']
                  ? 'column-error-border error-validation'
                  : '')
              "
              v-model="new_model['name']"
              :label="$t('field_name')"
              :hint="message"
            >
              <template v-slot:append>
                <q-icon
                  v-if="!new_model['validate'] || new_model['required_error']"
                  flat
                  dense
                  name="error"
                  size="24px"
                  color="red"
                >
                  <q-tooltip class="bg-red line-error-tooltip">
                    <template v-if="!new_model['validate']">
                      {{ message }}
                    </template>
                    <template v-if="new_model['required_error']">
                      {{ $t('field_required') }}
                    </template>
                  </q-tooltip>
                </q-icon>
              </template>
            </q-input>
          </div>
        </div>

        <div class="row full-width mb-10 mt-8" style="margin-bottom: 20px">
          <div class="full-width">
            <q-input
              v-model="new_model['description']"
              outlined
              type="textarea"
              autogrow
              :label="$t('description')"
            />
          </div>
        </div>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />

        <f-btn type="submit" class="q-mr-sm" :label="$t('save')" />
      </q-card-actions>
    </form>
    <q-inner-loading :showing="loading">
      <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
    </q-inner-loading>
  </q-card>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import { onlyNumbersCharactersSpaces } from 'src/utils/general';
import { subOrgsApiService } from 'src/services';
export default defineComponent({
  el: '#app',
    props: {
    is_edit: {
      type: Boolean,
      default: false,
    },
    name: {
      type: String || null,
      default: null,
    },
    description: {
      type: String || null,
      default: null,
    },
    id: {
      type: String || null,
      default: null,
    },
  },
  components: {},
  data() {
    return {
      message: this.$t('only_characters'),
    };
  },
  setup() {
    let model = {} as { [k: string]: any };

    return {
      new_model: ref(model),
      loading: ref(false),
    };
  },
  watch: {},
  mounted() {
    this.setNewModel();
    if (this.is_edit) {
      this.new_model['name'] = this.name;
      this.new_model['description'] = this.description;
    } else {
      this.new_model['name'] = '';
      this.new_model['description'] = '';
    }
  },
  methods: {
    setNewModel() {
      this.new_model['name'] = '';
      this.new_model['description'] = '';
      this.new_model['validate'] = true;
      this.new_model['required_error'] = false;
    },
    async submitNewColumFrom() {
      try {
        if (!this.validateRow(this.new_model)) {
          return;
        }
        this.loading = true;
        if (this.is_edit) {
          await this.onSubmitEdition();
        } else {
          await this.saveNewRow();
        }

        // close the dialog
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },
    async onSubmitEdition() {
      const data = {
        name: this.new_model['name'],
        description: this.new_model['description'],
      };
      await subOrgsApiService.update(this.id, data);
      this.setNewModel();
      const event = new CustomEvent('row_editted', {});
      document.dispatchEvent(event);
      notify.success(this.$t('SUB_ORGANIZATION_UPDATED'));
    },
    async saveNewRow() {
      const data = {
        name: this.new_model['name'],
        description: this.new_model['description'],
      };

      const response = await subOrgsApiService.create(data);
      if (!response.id) {
        throw new Error('Failed to create new record');
      }
      this.setNewModel();
      const event = new CustomEvent('row_added', { detail: response });
      document.dispatchEvent(event);
      notify.success('Record Created successfully');
    },

    validateRow(row: any) {
      let validate = true;

      if (!row['name'] || row['name'].length == 0) {
        row.required_error = true;
        return false;
      }

      if (!onlyNumbersCharactersSpaces(row['name'])) {
        row.validate = false;
        return false;
      }

      return validate;
    },
  },
});
</script>

<style lang="scss" scoped></style>
