<template>
  <span>{{ $t('select_all_sub_orgs_setting') }}</span>
  <f-toggle
    class="ml-10"
    size="xs"
    v-model="toggleValue"
    @update:model-value="saveSettings"
  />
  <q-inner-loading :showing="loading_settings">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { storeToRefs } from 'pinia';
import { useTranslate } from '@tolgee/vue';
import { useSettingStore } from 'src/store/main';
import type { dynamicObj } from 'src/pages/assets';
import { all_sub_org_setting } from 'src/constants';
import { ApiExceptions } from 'src/exceptions/index';
import { notify } from 'src/components/notifications/notify';

export default defineComponent({
  setup() {
    const { t } = useTranslate();
    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    return { t, settings_store, user_settings, loading_settings };
  },
  computed: {
    // Ensures strict boolean value for toggle
    toggleValue: {
      get(): boolean {
        const value = this.user_settings[all_sub_org_setting];
        // Normalize to strict boolean - handles string "true"/"false", numbers 1/0, etc.
        return value === true || value === 1 || value === '1' || value === 'true';
      },
      set(newValue: boolean) {
        // Ensure the value stored is always a strict boolean
        this.user_settings[all_sub_org_setting] = Boolean(newValue);
      },
    },
  },
  methods: {
    async saveSettings(value: boolean) {
      // Ensure strict boolean value
      const boolValue = Boolean(value);

      try {
        await this.settings_store.updateSetting(all_sub_org_setting, boolValue);

        // Dispatch appropriate event based on value
        if (boolValue) {
          const event = new CustomEvent('addAllSubOrg');
          document.dispatchEvent(event);
        } else {
          const event = new CustomEvent('removeAllSubOrg');
          document.dispatchEvent(event);
        }

        notify.success(this.t('MSG_SAVE'));
      } catch (e) {
        const msg = ApiExceptions.getErrorMessage(e as dynamicObj);
        notify.error(msg);
        logError(e);
      }
    },
  },
});
</script>
