<!--vbase-->
<template>
  <q-card style="width: 700px; max-width: 1060px">
    <q-toolbar class="text-white secondary-toolbar">
      <q-toolbar-title>
        <span class="text-weight-bold">{{ $t('add_user') }}</span>
      </q-toolbar-title>

      <q-btn flat round dense icon="close" v-close-popup />
    </q-toolbar>
    <q-card-section class="row items-center q-pb-none"> </q-card-section>

    <q-card-section>
      <div class="table-container col-sm-12 col-md-12 col-lg-12">
        <q-select
          outlined
          autofocus
          :loading="user_list_loading"
          v-model="selected_user_id"
          :options="filterUsersList"
          use-input
          emit-value
          map-options
          clearable
          @filter="filterUserbykeyword"
          :label="$t('select_user')"
        >
          <template v-slot:no-option>
            <q-item>
              <q-item-section class="text-grey">
                {{ $t('no_data_found') }}
              </q-item-section>
            </q-item>
          </template>
        </q-select>
      </div>
    </q-card-section>

    <q-card-section>
      <div class="table-container col-sm-12 col-md-12 col-lg-12">
        <q-checkbox
          :label="$t('remove_from_other_sub_orgs')"
          v-model="remove_from_others"
          size="50px"
          color="grey-6"
        />
      </div>
    </q-card-section>

    <q-card-actions align="right">
      <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />

      <f-btn @click="addUserToSubOrg()" class="q-mr-sm" :label="$t('save')" />
    </q-card-actions>
  </q-card>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin.js';
import { subOrgsApiService } from 'src/services';
import { useDropdownStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
export interface User {
  id: string;
  label: string;
  value: string;
}

export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  props: {
    sub_org_id: {
      type: String,
      default: '',
    },
    sub_org_users: {
      type: Array as () => User[],
      default: [] as any[],
    },
  },
  components: {},
  data() {
    return {};
  },
  mounted() {
    // Set initial filtered list
    this.filterUsersList = this.all_users.filter(
      (user) =>
        !this.sub_org_users.some((subUser) => subUser.id === user.value),
    );

    // Watch all_users and update filtered list when it changes
    this.$watch(
      () => this.all_users,
      (newVal) => {
        this.filterUsersList = newVal.filter(
          (user) =>
            !this.sub_org_users.some((subUser) => subUser.id === user.value),
        );
      },
      { deep: true },
    );
  },

  setup() {
    const filterUsersList = ref<User[]>([]);
    const dropdown_store = useDropdownStore();
    const { user_list_loading, usersList } = storeToRefs(dropdown_store);
    const all_users = ref<User[]>(dropdown_store.usersList as User[]);
    return {
      all_users,
      filterUsersList,
      usersList,
      remove_from_others: ref(false),
      selected_user_id: ref(''),
      user_list_loading,
    };
  },
  methods: {
    async addUserToSubOrg() {
      if (!this.selected_user_id) {
        notify.error(this.$t('select_user'));
        return;
      }

      this.showLoading();
      try {
        const data = {
          sub_org_id: this.sub_org_id,
          user_id: String(this.selected_user_id),
          remove_from_others: String(this.remove_from_others),
        };
        const response = await subOrgsApiService.addUserToSubOrg(data);
        if (!response.success) {
          throw response;
        }
        this.dispatchEvents();
        notify.success('Record Created successfully');
        this.selected_user_id = '';
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    dispatchEvents() {
      const event = new CustomEvent('user_added', {
        detail: this.selected_user_id,
      });
      document.dispatchEvent(event);

      const update_current_user_orgs_evt = new CustomEvent(
        'update_current_user_orgs',
        { detail: this.selected_user_id },
      );
      document.dispatchEvent(update_current_user_orgs_evt);
    },

    filterUserbykeyword(val: any, update: any) {
      const needle = val?.toString().toLowerCase().trim();

      update(() => {
        if (!needle) {
          // Show all users except those already in sub_org_users
          this.filterUsersList = this.all_users.filter(
            (user) =>
              !this.sub_org_users.some((subUser) => subUser.id === user.value),
          );
          return;
        }

        // Filter by name and remove already assigned users
        this.filterUsersList = this.all_users.filter((user: any) => {
          const label =
            typeof user.label === 'string'
              ? user.label.toLowerCase().trim()
              : '';
          return (
            label.includes(needle) &&
            !this.sub_org_users.some((subUser) => subUser.id === user.value)
          );
        });
      });
    },
  },
});
</script>

<style lang="scss" scoped></style>
