<!--vbase-->
<template>
  <div class="container">
    <div class="row v-m-10">
      <div class="col-sm-5 col-md-5 col-lg-5 display-flex align-items-center">
        <AllSubOrgSetting />
      </div>
      <div class="col-sm-7 col-md-7 col-lg-7"></div>
    </div>
    <div class="row mt-10 mb-25 justify-between">
      <div class="col-sm-6 col-md-6 col-lg-6">
        <q-input
          v-model="searchBy"
          dense
          :class="searchBy.length === 0 ? 'search-in-active' : 'search-active'"
          autofocus
          :placeholder="$t('search_suborganization')"
          outlined
          @update:model-value="updateSearchValue"
        >
          <template v-slot:append>
            <q-icon
              flat
              dense
              class="cursor-pointer"
              name="search"
              size="24px"
              color="primary"
              @click="searchBySubOrganization"
            />
          </template>
        </q-input>
      </div>
      <div class="row q-gutter-sm">
        <f-btn
          icon="add"
          :label="$t('new')"
          @click="display_create_dialog = true"
        />
      </div>
    </div>
    <div class="full-width">
      <DocBitsTable
        :rows="rows"
        :columns="columns"
        row-key="id"
        table-id="sub_organizations_table"
        :loading="processing"
        :features="{
          sorting: true,
          filtering: false,
          selection: false,
          bulkActions: false,
          rowActions: true,
          resizable: false,
          pagination: false,
          columnReorder: true,
          columnSettings: false,
          stickyFirstColumn: false,
          stickyLastColumn: true,
          clientSideSort: true,
        }"
        :row-actions="rowActions"
        :column-order="columnOrder"
        :pagination="sortState"
        no-data-label="no_record_found"
        table-height="calc(100vh - 210px)"
        flat-style
        @update:sorting="handleSort"
        @row-action="handleRowAction"
        @column-reorder="handleColumnReorder"
      >
        <!-- Name column -->
        <template #body-cell-name="{ row }">
          {{ row.name }}
        </template>

        <!-- Description column -->
        <template #body-cell-description="{ row }">
          {{ row.description || '-' }}
        </template>
      </DocBitsTable>
    </div>
  </div>

  <q-dialog v-model="delete_confirm" persistent>
    <q-card>
      <q-card-section
        class="row"
        style="justify-content: center; display: flex"
      >
        <q-avatar icon="warning" color="primary" />
      </q-card-section>

      <q-card-section class="row items-center">
        <span class="q-ml-sm">{{ $t('msg_delete') }}</span>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn
          appearance="cancel"
          :label="$t('cancel')"
          v-close-popup
        />
        <f-btn
          appearance="negative"
          :label="$t('delete')"
          v-close-popup
          @click="deleteRow()"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>

  <q-dialog
    v-model="display_create_dialog"
    persistent
    @keydown.esc="display_create_dialog = false"
  >
    <Create></Create>
  </q-dialog>

  <q-dialog
    v-model="display_users_dialog"
    persistent
    transition-show="scale"
    transition-hide="scale"
    @keydown.esc="display_users_dialog = false"
  >
    <q-card style="width: 700px; max-width: 1060px; display: flex; flex-direction: column;">
      <q-toolbar class="secondary-toolbar" style="flex-shrink: 0">
        <q-toolbar-title>
          <span class="text-weight-bold text-white">
            {{ selectedName }} {{ $t('users') }}
          </span>
        </q-toolbar-title>

        <q-btn flat round dense icon="close" class="text-white" v-close-popup />
      </q-toolbar>

      <q-card-section style="flex: 1; overflow-y: auto">
        <UsersList :sub_org_id="selectedId"></UsersList>
      </q-card-section>
    </q-card>
  </q-dialog>

  <q-dialog
    v-model="sub_organiztion_form"
    persistent
    @keydown.esc="sub_organiztion_form = false"
  >
    <Create
      :is_edit="true"
      :name="sub_org_edit_name"
      :id="sub_org_edit_id"
      :description="sub_org_edit_desc"
    ></Create>
  </q-dialog>
  <q-inner-loading :showing="processing">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>
</template>

<script lang="ts">
import { debounce } from 'quasar';
import Create from './Create.vue';
import cache from 'src/utils/cache';
import { storeToRefs } from 'pinia';
import UsersList from './UsersList.vue';
import stringUtil from 'src/utils/string';
import type { dynamicObj } from 'src/pages/assets';
import { useUserStore } from 'src/store/main';
import { ApiExceptions } from 'src/exceptions';
import { subOrgsApiService } from 'src/services';
import { defineComponent, ref, computed, reactive } from 'vue';
import { sub_org_sort_order, CONSTANTS } from 'src/constants';
import { UserSubOrg } from 'src/utils/organization/index';
import { getUserDetailFromkey } from 'src/utils/UserDetails';
import { notify } from 'src/components/notifications/notify';
import { useDropdownStore, useSettingStore } from 'src/store/main';
import AllSubOrgSetting from 'src/pages/Settings/SubOrganizations/AllSubOrgSetting.vue';
import { DocBitsTable } from 'src/components/Table';
import type {
  UnifiedTableColumn,
  RowActionItem,
  SortEventPayload,
  RowActionPayload,
} from 'src/components/Table';
import { useTranslate } from '@tolgee/vue';

export default defineComponent({
  el: '#app',
  mixins: [stringUtil, cache],
  components: {
    Create,
    UsersList,
    AllSubOrgSetting,
    DocBitsTable,
  },
  data() {
    return {
      dialog: false,
      current_user_id: '',
      searchBy: ref(''),
      sub_organiztion_form: ref(false),
      sub_org_edit_name: ref(''),
      sub_org_edit_id: ref(''),
      sub_org_edit_desc: ref(''),
      sub_org_sort_order: sub_org_sort_order,
    };
  },
  watch: {
    loading_settings: {
      handler: function (newVal: boolean, oldVal: boolean) {
        if (newVal === false) {
          this.loadSavedSort();
        }
      },
    },
  },
  mounted() {
    this.initView();
    document.addEventListener('row_added', this.rowAdded);
    document.addEventListener('row_editted', this.rowEditted);
    document.addEventListener('sub_org_user_removed', this.subOrgUserRemoved);
    document.addEventListener(
      'update_current_user_orgs',
      this.updateCurrentUserOrganizations,
    );
    this.debounceSearchInputFunc = debounce(() => {
      this.searchBySubOrganization();
    }, 500);
    this.loadColumnOrder();
  },
  unmounted() {
    document.removeEventListener('row_added', this.rowAdded);
    document.removeEventListener('row_editted', this.rowEditted);
    document.removeEventListener(
      'sub_org_user_removed',
      this.subOrgUserRemoved,
    );
    document.removeEventListener(
      'update_current_user_orgs',
      this.updateCurrentUserOrganizations,
    );
  },
  methods: {
    async initView() {
      try {
        this.processing = true;
        this.loadSavedSort();
        await this.getList();
        this.current_user_id = getUserDetailFromkey('id');
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },
    loadColumnOrder() {
      const savedOrderString = this.getDataByKey(CONSTANTS.sub_org_columns_order);
      if (savedOrderString) {
        this.columnOrder = JSON.parse(savedOrderString as string);
      }
    },
    loadSavedSort() {
      const sortOrderStr = this.user_settings[sub_org_sort_order];
      if (sortOrderStr) {
        const sortOrder = JSON.parse(sortOrderStr);
        // Update the reactive sortState to trigger DocBitsTable's clientSideSort
        this.sortState.sortBy = sortOrder.sort_by;
        this.sortState.descending = sortOrder.sort_order === 'desc';
      }
    },
    updateSearchValue() {
      this.debounceSearchInputFunc();
    },
    searchBySubOrganization() {
      this.request_params = {} as dynamicObj;
      const searchVal = this.searchBy.trim();
      if (searchVal) {
        this.request_params['search'] = searchVal;
      }
      this.getList(this.request_params);
    },
    openForm(row: any) {
      if (row) {
        this.sub_org_edit_name = row.name;
        this.sub_org_edit_id = row.id;
        this.sub_org_edit_desc = row.description;
      }
      this.sub_organiztion_form = true;
    },
    rowAdded(e: any) {
      if (!e || !e.detail) {
        return;
      }
      this.display_create_dialog = false;
      this.addNewRow(e.detail);
      this.resetSubOrgsList();
    },
    rowEditted() {
      this.sub_organiztion_form = false;
      this.initView();
    },

    async deleteRow() {
      try {
        if (!this.delete_id) {
          return;
        }
        this.processing = true;
        await subOrgsApiService.delete(this.delete_id);

        // Remove from local rows array
        let delete_index = -1;
        this.rows.forEach((row: any, index: any) => {
          if (row['id'] === this.delete_id) {
            delete_index = index;
          }
        });

        if (delete_index !== -1) {
          this.rows.splice(delete_index, 1);
        }

        await this.updateCurrentUserSubOrgs(this.delete_id);
        await this.resetSubOrgsList();
        this.delete_id = '';
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },

    async getList(params: any = {}) {
      const response = await subOrgsApiService.getAll(params);
      this.prepareRows(response);
    },

    prepareRows(data: any) {
      if (!data) {
        return;
      }
      this.rows = [] as any;
      for (let [index, item] of Object.entries(data)) {
        const row = item as dynamicObj;
        this.addNewRow(row);
      }
    },

    addNewRow(row: any) {
      let newRow: dynamicObj = { ...row };
      this.rows.push(newRow);
      return this.rows.length.toString() as string;
    },

    manageUsers(row: any) {
      this.selectedId = row.id;
      this.selectedName = row.name;
      this.display_users_dialog = true;
    },

    async updateCurrentUserSubOrgs(deleted_sub_org_id: string) {
      const is_current_sub_org_id = deleted_sub_org_id === this.sub_org_id;
      if (is_current_sub_org_id) {
        await this.refreshUserOrganizations();
        await this.removeCurrentOrgFromProfile();
      }

      if (!is_current_sub_org_id) {
        const sub_org = UserSubOrg.getSubOrgbyId(deleted_sub_org_id);
        // user orgs has sub org id
        if (sub_org && Object.keys(sub_org).length !== 0) {
          await this.refreshUserOrganizations();
        }
      }
    },

    subOrgUserRemoved(e: any) {
      if (!e || !e.detail) {
        return;
      }
      // if user id and current user id same then update
      if (e.detail.user_id !== this.current_user_id) {
        return;
      }

      this.removeSubOrgFromCurrentUserList(e.detail);
    },

    async removeSubOrgFromCurrentUserList(data: any) {
      const sub_org_id = await this.getSubOrgId();
      if (sub_org_id == data.sub_org_id) {
        await this.removeCurrentOrgFromProfile();
      }
      this.refreshUserOrganizations();
    },

    async removeCurrentOrgFromProfile() {
      await UserSubOrg.setSubOrgId('');
      this.sub_org_id = '';
      this.sub_org_name = '';
      this.getMainOrganization();
    },

    updateCurrentUserOrganizations(e: any) {
      if (!e || !e.detail) {
        return;
      }
      // if user id and current user id same then update
      if (e.detail !== this.current_user_id) {
        return;
      }

      this.refreshUserOrganizations();
    },
    handleSort(payload: SortEventPayload) {
      // Update sortState for DocBitsTable's clientSideSort
      this.sortState.sortBy = payload.column;
      this.sortState.descending = payload.direction === 'desc';

      // Persist sort preference to user settings
      this.persistSort(payload.column, payload.direction);
    },
    async persistSort(sortBy: string, sortOrder: string) {
      const sortObj = { sort_by: sortBy, sort_order: sortOrder };
      try {
        await this.updateSetting(sub_org_sort_order, JSON.stringify(sortObj));
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
    handleRowAction(payload: RowActionPayload) {
      if (payload.action === 'manage-users') {
        this.manageUsers(payload.row);
      } else if (payload.action === 'edit') {
        this.openForm(payload.row);
      } else if (payload.action === 'delete') {
        this.delete_id = payload.rowId;
        this.delete_confirm = true;
      }
    },
    handleColumnReorder(newOrder: string[]) {
      this.columnOrder = newOrder;
      this.setDataToLocalStorage(
        CONSTANTS.sub_org_columns_order,
        JSON.stringify(newOrder),
      );
    },
  },
  setup() {
    const { t } = useTranslate();
    const user_store = useUserStore();
    const { getSubOrgId, refreshUserOrganizations, getMainOrganization } =
      user_store;
    const { sub_org_id, sub_org_name } = storeToRefs(user_store);

    const dropdown_store = useDropdownStore();
    const { resetSubOrgsList } = dropdown_store;

    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    const { updateSetting } = settings_store;

    // Column definitions for DocBitsTable
    const columns = computed<UnifiedTableColumn[]>(() => [
      {
        name: 'name',
        label: t.value('name'),
        field: 'name',
        sortable: true,
        align: 'left',
      },
      {
        name: 'description',
        label: t.value('DESCRIPTION'),
        field: 'description',
        sortable: true,
        align: 'left',
      },
    ]);

    // Row actions for manage users, edit, and delete
    const rowActions: RowActionItem[] = [
      {
        key: 'manage-users',
        label: 'manage_users',
        icon: 'people',
        color: 'primary',
      },
      {
        key: 'edit',
        label: 'edit',
        icon: 'edit',
        color: 'grey-7',
      },
      {
        key: 'delete',
        label: 'delete',
        icon: 'delete',
        color: 'negative',
        separator: true,
      },
    ];

    // Sort state for DocBitsTable's clientSideSort feature
    const sortState = reactive({
      sortBy: null as string | null,
      descending: false,
    });

    return {
      debounceSearchInputFunc: {} as any,
      refreshUserOrganizations,
      getMainOrganization,
      resetSubOrgsList,
      updateSetting,
      getSubOrgId,
      sub_org_id,
      sub_org_name,
      display_users_dialog: ref(false),
      request_params: ref({} as dynamicObj),
      display_create_dialog: ref(false),
      selectedId: ref(''),
      selectedName: ref(''),
      columns,
      rowActions,
      columnOrder: ref<string[]>([]),
      sortState,
      rows: ref([] as any),
      delete_confirm: ref(false),
      delete_id: ref(''),
      processing: ref(false),
      user_settings,
      loading_settings,
      t,
    };
  },
});
</script>

<style scoped>
.main-button {
  display: flex;
  margin-left: 10px;
}

.main-buttons {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: flex-end;
}

</style>
